import{_ as t,o as a,c as s,a5 as r}from"./chunks/framework.DrDMl0tG.js";const u=JSON.parse('{"title":"Benchmarks","description":"","frontmatter":{},"headers":[],"relativePath":"sections/BenchmarkOverview.md","filePath":"sections/BenchmarkOverview.md"}'),n={name:"sections/BenchmarkOverview.md"};function o(i,e,h,d,m,l){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="benchmarks" tabindex="-1">Benchmarks <a class="header-anchor" href="#benchmarks" aria-label="Permalink to &quot;Benchmarks&quot;">​</a></h1><p>Each benchmark below runs RaiSim and another engine or library on the same machine and the same workload. The pages list the machine, compiler, versions and number of runs, what is checked, and how to repeat the measurements.</p><table tabindex="0"><thead><tr><th>Area</th><th>Benchmark</th><th>Compared with</th><th>Result</th></tr></thead><tbody><tr><td>Physics engines</td><td><a href="./Benchmark.html">RaiSim vs MuJoCo</a></td><td>MuJoCo</td><td>Ten single-thread workloads (articulated dynamics, contacts, closed loops, ray queries, deformables): RaiSim <strong>2.4–147×</strong> faster.</td></tr><tr><td></td><td><a href="./BenchmarkNewton.html">RaiSim vs Newton</a></td><td>Newton (MuJoCo Warp on a GPU)</td><td>CPU worlds against GPU worlds: <strong>2× or more</strong> physics throughput per dollar at every scale measured, <strong>9.9–254×</strong> with 1–64 worlds.</td></tr><tr><td>Deformable solids</td><td><a href="./LinearElasticityBenchmarks.html">Linear elasticity</a></td><td>MFEM, scikit-fem</td><td>The same tetrahedral meshes: a cold solve of 41,472 tetrahedra takes 337 ms in RaiSim, 456 ms in MFEM and 5.7 s in scikit-fem.</td></tr><tr><td>Ray casting</td><td><a href="./BenchmarkVoxelRayCasting.html">Voxel ray casting</a></td><td>OpenVDB, NanoVDB, Bonxai, OctoMap; on the CPU and the GPU</td><td>Exact lidar rays <strong>1.7–34×</strong> faster on one CPU core and <strong>1.3–1.8×</strong> faster than NanoVDB in CUDA on the GPU; a GPU scan of 65,536 rays is <strong>27–34×</strong> faster than on one CPU core.</td></tr></tbody></table><h2 id="how-the-measurements-are-made" tabindex="-1">How the measurements are made <a class="header-anchor" href="#how-the-measurements-are-made" aria-label="Permalink to &quot;How the measurements are made&quot;">​</a></h2><ul><li><strong>Same work.</strong> Both sides load the same models and scenes, with the same time step, step count, rays or meshes. Where the engines model something differently (contact, deformable models), the page says how, and which results are left out.</li><li><strong>Checked results.</strong> The comparisons check what both sides can compute alike: ray hits and their distances, residuals against reference solutions, or finite and settled states. Runs that fail, such as a simulation that becomes unstable, are left out of the speedups.</li><li><strong>CPU timings</strong> use one thread pinned to one core, with the BLAS and OpenMP thread counts set to one, except in the comparison of parallel worlds with Newton. <strong>GPU timings</strong> use GPU timer queries or CUDA events, and wall-clock time where the CPU waits for the result.</li><li><strong>Repeats.</strong> Each page states how many runs it took and whether it reports the median or the best.</li></ul><p>Timings depend on the machine, compiler, driver and scene. To time your own workload with the binary package, see <a href="./BuildAndTest.html#timing-examples">Build, Test, and Benchmark</a> and the <a href="./examples/benchmark/anymal_standing_benchmark.html">benchmark examples</a>. <a href="./Performance.html">Performance</a> explains the settings that change RaiSim&#39;s speed the most, such as convex collision meshes.</p>',6)])])}const p=t(n,[["render",o]]);export{u as __pageData,p as default};
